/// <summary>
/// CB129 Cancellation of Open SO/PO lines
/// </summary>
[DataContractAttribute]
class METSalesCancelContract implements SysOperationValidatable
{
    ReasonCode              reasonCode;
    METOrderExtractStatus   extractedStatus;
    container               salesLineRecords;

}

Method.Source:
/// <summary>
/// parmExtractedStatus
/// </summary>
/// <param name = "_extractedStatus">_extractedStatus</param>
/// <returns>METOrderExtractStatus</returns>
[DataMemberAttribute]
public METOrderExtractStatus parmExtractedStatus(METOrderExtractStatus _extractedStatus = extractedStatus)
{
    extractedStatus = _extractedStatus;
    return extractedStatus;
}

/// <summary>
/// parmReasonCode
/// </summary>
/// <param name = "_reasonCode">_reasonCode</param>
/// <returns>ReasonCode</returns>

[DataMemberAttribute]
public ReasonCode parmReasonCode(ReasonCode _reasonCode = reasonCode)
{
    reasonCode = _reasonCode;
    return reasonCode;
}

/// <summary>
/// parmSalesLineRecords
/// </summary>
/// <param name = "_salesLineRecords">_salesLineRecords</param>
/// <returns>container</returns>
[DataMemberAttribute,
SysOperationControlVisibilityAttribute(false)]
public container parmSalesLineRecords(container _salesLineRecords = salesLineRecords)
{
    salesLineRecords = _salesLineRecords;
    return salesLineRecords;
}

/// <summary>
/// validate
/// </summary>
/// <returns>boolean</returns>
public boolean validate()
{
    boolean ret = true;
    if(!this.parmReasonCode())
    {
        ret = checkFailed("@MET:ReasonCodeMandatory");
    }
    return ret;
}
